package io.knowledgebrain.content;
import java.util.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class QuestionRulesTest {
 @Test void resolutionNeedsExplicitNonblankAnswerWhileOpenMayKeepADraft(){for(String s:List.of("", " \r\n\t", "\u3000"))assertThrows(org.springframework.web.server.ResponseStatusException.class,()->QuestionRules.input(new QuestionStore.Input("Question","",s,"ANSWERED")));assertDoesNotThrow(()->QuestionRules.input(new QuestionStore.Input("Question","","Draft","OPEN")));assertDoesNotThrow(()->QuestionRules.input(new QuestionStore.Input("Question","","My answer","ANSWERED")));assertThrows(org.springframework.web.server.ResponseStatusException.class,()->QuestionRules.input(new QuestionStore.Input("Question","","Answer","VERIFIED")));}
 @Test void unicodeBoundsAndExactMultilineText(){var v=new QuestionStore.Input("😀".repeat(200),"a".repeat(16384),"\r\n\t"+"b".repeat(16381),"ANSWERED");assertDoesNotThrow(()->QuestionRules.input(v));for(var invalid:List.of(new QuestionStore.Input(" ","","","OPEN"),new QuestionStore.Input("a\nb","","","OPEN"),new QuestionStore.Input("😀".repeat(201),"","","OPEN"),new QuestionStore.Input("q","a".repeat(16385),"","OPEN"),new QuestionStore.Input("q","","b".repeat(16385),"OPEN"),new QuestionStore.Input("q","\ud800","","OPEN"),new QuestionStore.Input("q","","\u007f","OPEN")))assertThrows(org.springframework.web.server.ResponseStatusException.class,()->QuestionRules.input(invalid));}
 @Test void uuidAndTraceValidation(){assertThrows(org.springframework.web.server.ResponseStatusException.class,()->QuestionRules.id(UUID.randomUUID().toString()));assertThrows(org.springframework.web.server.ResponseStatusException.class,()->QuestionRules.trace("0".repeat(32)));}
}
